				text18 = (string.IsNullOrWhiteSpace(text18) ? P(value5, "dev_hdd0") : Resolve(text18.Replace("$(EmulatorDir)", value5.TrimEnd('\\', '/') + Path.DirectorySeparatorChar), program));
				string text19 = P(text18, "home");
