				{
					text10 = ".;ini";
				}
				foreach (string item in text10.Split(';').Take(8))
				{
					string text11 = P(Resolve(item, text9), "mame.ini");
					if (string.Equals(text11, text4, StringComparison.OrdinalIgnoreCase))
					{
